.ds-facts dt { color: var(--c-ink-muted, #4D5A6A); font-size: var(--fs-sm, 0.875rem); }
.ds-facts dd { font-weight: var(--fw-medium, 500); font-size: var(--fs-sm, 0.875rem); }
.ds-next-step { border: 1px solid var(--c-accent-line, #8FB0E3); border-radius: var(--radius, 4px); background: var(--c-surface, #FFFFFF); }
.ds-next-step__head { display: flex; align-items: center; gap: var(--s-2, 0.5rem); padding: var(--s-2, 0.5rem) var(--s-3, 0.75rem); background: var(--c-accent-soft, #E8F0FC); border-bottom: 1px solid var(--c-accent-line, #8FB0E3); font-size: var(--fs-sm, 0.875rem); font-weight: var(--fw-bold, 650); color: var(--c-accent, #1F5FBF); border-radius: var(--radius, 4px) var(--radius, 4px) 0 0; }
.ds-next-step__body { padding: var(--s-3, 0.75rem); display: grid; gap: var(--s-3, 0.75rem); }
.ds-next-step__what { font-size: var(--fs-lg, 1.1875rem); font-weight: var(--fw-bold, 650); }
.ds-tag {
  display: inline-flex; align-items: center; gap: 0.35em; width: max-content; max-width: 100%;
  padding: 0.125rem 0.45rem; border-radius: var(--radius-sm, 3px); border: 1px solid;
  font-size: var(--fs-xs, 0.8125rem); font-weight: var(--fw-bold, 650); line-height: 1.4;
}
.ds-tag .ds-icon { width: 0.9rem; height: 0.9rem; stroke-width: 2; }
.ds-tag--danger  { background: var(--c-danger-soft, #FDECEA);  color: var(--c-danger, #B42318);  border-color: var(--c-danger-line, #E7A39C); }
.ds-tag--warning { background: var(--c-warning-soft, #FFF4E0); color: var(--c-warning, #8A5300); border-color: var(--c-warning-line, #DDB46A); }
.ds-tag--success { background: var(--c-success-soft, #E6F4EA); color: var(--c-success, #1E6B3A); border-color: var(--c-success-line, #93C6A3); }
.ds-tag--neutral { background: var(--c-neutral-soft, #EEF1F5); color: var(--c-neutral, #4D5A6A); border-color: var(--c-neutral-line, #B8C2CE); }
.ds-tag--info    { background: var(--c-info-soft, #E8F0FC);    color: var(--c-info, #1F5FBF);    border-color: var(--c-info-line, #8FB0E3); }
.ds-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s-2, 0.5rem);
  min-height: var(--target-min, 2.5rem); padding: 0 var(--s-4, 1rem);
  font: var(--fw-medium, 500) var(--fs-sm, 0.875rem) / 1.2 var(--font, system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", "Helvetica Neue", Arial, sans-serif);
  border-radius: var(--radius, 4px); border: 1px solid var(--c-accent, #1F5FBF);
  background: var(--c-accent, #1F5FBF); color: var(--c-accent-ink, #FFFFFF); cursor: pointer;
  transition: background-color var(--t-fast, 150ms) ease-out, border-color var(--t-fast, 150ms) ease-out;
}
.ds-btn:hover { background: var(--c-accent-hover, #194E9E); border-color: var(--c-accent-hover, #194E9E); }
.ds-btn--secondary { background: var(--c-surface, #FFFFFF); color: var(--c-accent, #1F5FBF); border-color: var(--c-line-strong, #747F8D); }
.ds-btn--secondary:hover { background: var(--c-accent-soft, #E8F0FC); border-color: var(--c-accent, #1F5FBF); }
.ds-btn[disabled] { background: var(--c-neutral-soft, #EEF1F5); color: var(--c-ink-muted, #4D5A6A); border-color: var(--c-line, #B8C2CE); cursor: not-allowed; }
.ds-btn-row { display: flex; flex-wrap: wrap; gap: var(--s-2, 0.5rem); align-items: center; }
.ds-example-note { display: flex; gap: var(--s-2, 0.5rem); align-items: flex-start; font-size: var(--fs-xs, 0.8125rem); color: var(--c-ink-muted, #4D5A6A); }
@media (max-width: 760px) { .ds-btn { min-height: var(--target-touch, 2.75rem); } }
@media (max-width: 760px) {
  .ds-facts > div { grid-template-columns: var(--icon, 1.125rem) minmax(0, 1fr); }
  .ds-facts dd { grid-column: 2; }
}
@media (prefers-reduced-motion: reduce) { .ds-btn { transition-duration: 0ms; } }
.ds-btn { box-sizing: border-box; }

.ds-preview { color: var(--c-ink, #1B2430); font: var(--fw-regular, 400) var(--fs-md, 1rem) / var(--lh-body, 1.5) var(--font, system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", "Helvetica Neue", Arial, sans-serif); font-variant-numeric: tabular-nums; }
