.ds-preview :focus-visible { outline: var(--focus-width, 2px) solid var(--c-focus, #1F5FBF); outline-offset: 2px; }
.ds-icon { width: var(--icon, 1.125rem); height: var(--icon, 1.125rem); flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; vertical-align: -0.2em; }
.ds-icon--sm { width: 0.9rem; height: 0.9rem; }
