.ds-timeline { list-style: none; position: relative; display: grid; }
.ds-timeline li { position: relative; display: grid; grid-template-columns: 2rem minmax(0, 1fr); gap: var(--s-3, 0.75rem); padding-bottom: var(--s-3, 0.75rem); }
