.ds-timeline li:last-child::before { display: none; }
.ds-timeline li.is-done::before { background: var(--c-success-line, #93C6A3); }
.ds-node { width: 2rem; height: 2rem; border-radius: 50%; display: grid; place-items: center; border: 2px solid var(--c-line-strong, #747F8D); background: var(--c-surface, #FFFFFF); color: var(--c-ink-muted, #4D5A6A); position: relative; z-index: 1; }
.ds-node .ds-icon { width: 1rem; height: 1rem; stroke-width: 2.25; }
