.ds-is-now .ds-node { border-color: var(--c-accent, #1F5FBF); color: var(--c-accent-ink, #FFFFFF); background: var(--c-accent, #1F5FBF); }
.ds-is-later .ds-node { border-style: dashed; }
.ds-timeline__text { display: grid; gap: 2px; padding-top: 0.2rem; font-size: var(--fs-sm, 0.875rem); }
.ds-timeline__text b { font-weight: var(--fw-bold, 650); }
.ds-ds-preview .ds-timeline__text { font-size: var(--fs-md, 1rem); }
.ds-node { box-sizing: border-box; }

